import{_ as d,C as n,o as p,c,a3 as t,E as l,j as a,a as i}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"NACP 生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"transport/nacp/lifecycle.md","filePath":"transport/nacp/lifecycle.md","lastUpdated":1788343005000}'),r={name:"transport/nacp/lifecycle.md"};function s(b,e,u,A,f,h){const o=n("VitePressMermaid");return p(),c("div",null,[e[0]||(e[0]=t('<h1 id="nacp-生命周期" tabindex="-1">NACP 生命周期 <a class="header-anchor" href="#nacp-生命周期" aria-label="Permalink to &quot;NACP 生命周期&quot;">​</a></h1><p>NACP 生命周期分为 <code>NApp 链路生命周期</code>和<code>消息生命周期</code>。</p><p>前者维护了一个NApp链接情况，后者用于维护一个消息的情况。</p><h2 id="app-链路生命周期" tabindex="-1">App 链路生命周期 <a class="header-anchor" href="#app-链路生命周期" aria-label="Permalink to &quot;App 链路生命周期&quot;">​</a></h2><p>每个已完成 Register 的 App ID 都处于以下状态之一：</p>',5)),l(o,{value:`stateDiagram-v2
    [*] --> online: Reg 成功
    online --> offline: 断连 / ACK超时
    offline --> online: 宽限期内 Reg
    offline --> dropped: 宽限期结束
    online --> dropped: 收到 UnReg
    dropped --> [*]`}),e[1]||(e[1]=t('<table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>出站消息</th></tr></thead><tbody><tr><td><code>online</code></td><td>App 已绑定且当前可达</td><td>立即尝试发送</td></tr><tr><td><code>offline</code></td><td>App 暂时不可达，等待重新连接</td><td>进入 积压表 暂存</td></tr><tr><td><code>dropped</code></td><td>App 已被彻底遗忘</td><td>放弃并结算相关等待方</td></tr></tbody></table><h3 id="online" tabindex="-1">online <a class="header-anchor" href="#online" aria-label="Permalink to &quot;online&quot;">​</a></h3><p>Register 握手成功后，NACP 建立 App ID 与 NACT Peer 的绑定，App 进入 <code>online</code>。</p><p>发往该 App 的消息会先进入 <code>积压表Backlog</code>，再立即尝试提交给对应 Peer。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>正常情况下 Backlog 只是出站通道，不会长期持有消息。</p></div><h3 id="offline" tabindex="-1">offline <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;offline&quot;">​</a></h3><p>当出现以下情况，会把 NApp 标记为 <code>offline</code>：</p><ul><li>承载该 NApp 的 NACT Peer 断开。</li><li>发往该 NApp 的可靠消息超过 <code>ackTimeoutMs</code> 仍未收到 ACK。</li></ul><p>进入 <code>offline</code> 时，NACP 会：</p><ul><li>保留 App ID、请求等待方和订阅记录，包括 AutoSubscribe。</li><li>将已经发出但尚未收到 ACK 的消息移回 Backlog 队首。</li><li>启动 <code>reconnectGraceMs</code> 宽限计时。</li><li>将后续出站消息继续加入 Backlog。</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>注意区分 ACK 超时和 Req 超时。前者用于判断链路可达性，不是 Request 的业务处理时限。</p></div><h3 id="re-online" tabindex="-1">Re-online <a class="header-anchor" href="#re-online" aria-label="Permalink to &quot;Re-online&quot;">​</a></h3><p>同一 App ID 在宽限期内重新完成 Register 后，NACP 会取消宽限计时，并按 Backlog 中的原始顺序补发消息。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>可靠消息可能因此被重复发送，接收方会再次回复 ACK，但在去重记录有效期间不会重复处理。</p></div><h3 id="dropped" tabindex="-1">dropped <a class="header-anchor" href="#dropped" aria-label="Permalink to &quot;dropped&quot;">​</a></h3><p>以下情况会使 App 进入 <code>dropped</code>：</p><ul><li><code>offline</code> 超过重连宽限期。</li><li>对端主动发送 Unregister。</li></ul><p>进入 <code>dropped</code> 后，NACP 会彻底清理该 App 的协议状态：</p><ul><li>放弃 Backlog 和 ACK 等待表中的消息，并以 <code>false</code> 结算对应发送等待方。</li><li>reject 仍在等待 Response 的调用。</li><li>移除 SubscribeTable 与 ListenTable 中属于该 App 的记录。</li><li>结束显式订阅与 AutoSubscribe 的本地监听。</li><li>删除该 App 的入站去重记录和链路绑定。</li></ul><p>Unregister 表示对端明确离开，因此不会经过 <code>offline</code> 或等待宽限期。</p><h2 id="消息生命周期" tabindex="-1">消息生命周期 <a class="header-anchor" href="#消息生命周期" aria-label="Permalink to &quot;消息生命周期&quot;">​</a></h2><h3 id="需要-ack-的消息" tabindex="-1">需要 ACK 的消息 <a class="header-anchor" href="#需要-ack-的消息" aria-label="Permalink to &quot;需要 ACK 的消息&quot;">​</a></h3><p>Request、Response、Signal、Register、Unregister、Subscribe 和 Unsubscribe 使用两段出站队列：</p>',23)),l(o,{value:`stateDiagram-v2
    [*] --> backlog: NACP 接收消息
    backlog --> ackPending: 目标在线，提交给 NACT
    ackPending --> completed: 收到 ACK
    ackPending --> backlog: 链路离线
    backlog --> failed: 逐出 / App dropped
    ackPending --> failed: 逐出 / App dropped
    completed --> [*]
    failed --> [*]`}),e[2]||(e[2]=a("p",null,[a("code",null,"BacklogTable 积压表"),i(" 保存尚未出线或等待重发的消息，"),a("code",null,"AckPendingTable确认表"),i(" 保存已经提交给 NACT、正在等待 ACK 的消息。")],-1)),e[3]||(e[3]=a("h3",{id:"notify与ackmessage",tabindex:"-1"},[i("Notify与AckMessage "),a("a",{class:"header-anchor",href:"#notify与ackmessage","aria-label":'Permalink to "Notify与AckMessage"'},"​")],-1)),e[4]||(e[4]=a("p",null,"Notify 和 Ack 不等待 ACK，也不进入 AckPendingTable：",-1)),l(o,{value:`stateDiagram-v2
    [*] --> backlog: NACP 接收消息
    backlog --> completed: 目标在线，提交给 NACT
    backlog --> waiting: 目标离线
    waiting --> completed: 重连后成功发出
    backlog --> failed: 容量拒绝 / 逐出
    waiting --> failed: 容量逐出 / App dropped
    completed --> [*]: 返回 true
    failed --> [*]: 返回 false`}),e[5]||(e[5]=t('<p>消息停留在离线 Backlog 中时，对应 Promise 保持 pending。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Notify 是过程消息，最终结果由 Response 保证。</p><p>因此容量不足时会优先放弃 Notify，避免过程流挤占最终消息。</p><p>如果所有Notify都被放弃了，则按照FIFO顺序移除最早的消息。</p></div><h2 id="response-等待" tabindex="-1">Response 等待 <a class="header-anchor" href="#response-等待" aria-label="Permalink to &quot;Response 等待&quot;">​</a></h2><p>NACP区分<code>消息已接收</code>和<code>消息已处理</code>两个行为。</p><p>对于消息接收限时，默认为10s，超时则认为对端NApp离线。</p><p>对于消息处理限时，则区分：</p><table tabindex="0"><thead><tr><th>操作</th><th>Response 等待时间</th></tr></thead><tbody><tr><td><code>request</code></td><td>不设置业务超时</td></tr><tr><td><code>register</code> / <code>unregister</code></td><td>10 秒</td></tr><tr><td><code>subscribe</code> / <code>unsubscribe</code></td><td>10 秒</td></tr></tbody></table><p>只要 App 仍在 <code>online</code> 或重连宽限期内，Response 等待方和 <a href="/transport/nacp/auto-subscribe">AutoSubscribe</a> 都会保留。</p><h2 id="容量限制" tabindex="-1">容量限制 <a class="header-anchor" href="#容量限制" aria-label="Permalink to &quot;容量限制&quot;">​</a></h2><p>BacklogTable 与 AckPendingTable 默认各自最多保存 1024 条、4 GiB。</p><p>两个队列分别执行容量限制，容量限制由<a href="/napp/construction"><code>queueMaxBytes</code></a>和<a href="/napp/construction"><code>queueMaxCount</code></a>决定</p><p>Backlog 溢出时按以下顺序处理：</p><ol><li>新消息是 Notify：拒绝该 Notify，<code>notify()</code> 返回 <code>false</code>。</li><li>新消息是其他类型：先逐出最早的 Notify。</li><li>仍然超限：按 FIFO 逐出最早的其他消息。</li></ol><p>AckPendingTable 不包含 Notify，溢出时按 FIFO 逐出等待 ACK 的消息，并以 <code>false</code> 结算对应 ACK 等待方。</p><p>具体告警可以通过 <code>nacp:internal:backlog:warning</code> 与 <code>nacp:internal:ack:warning</code> 观察。详见<a href="/transport/nacp/observability">可观测</a></p><h2 id="nacp-终止" tabindex="-1">NACP 终止 <a class="header-anchor" href="#nacp-终止" aria-label="Permalink to &quot;NACP 终止&quot;">​</a></h2><p><code>nacp.terminate()</code> 会立即结束全部 NACP 状态：</p><ul><li>reject 所有 Response 等待方。</li><li>移除全部 EventBus 转发监听和本地订阅记录。</li><li>清空链路、Backlog、ACK、去重记录与计时器。</li><li>以 <code>false</code> 结算尚未完成的发送等待方。</li></ul><p>各阶段使用的数据结构见<a href="/transport/nacp/tables">内部记录表</a>，生命周期事件见<a href="/transport/nacp/observability">可观测</a>。</p>',19))])}const P=d(r,[["render",s]]);export{g as __pageData,P as default};
